        "text": "{\n  \"schema_version\": 1,\n  \"outcome\": \"Given a selfie key and an already configured recognition helper, query the registered-search collection and return every matched search with its complete recorded purchase evidence through one service entrypoint.\",\n  \"constraints\": \"Add public static forSelfie($s3Key, \\\\App\\\\Helpers\\\\AmazonFaceRecognitionService $amazon) in the allowed existing service. The supplied helper is already configured by the caller. Query SearchRecognitionRegistration::COLLECTION_ID using the exact caller-supplied key and existing helper default maxFaces/threshold. Return the complete existing forMatches result and preserve its exceptions on failed/sentinel/invalid inputs. Preserve existing methods and dependencies byte-for-byte where outside the addition. PHP 7.4 / Laravel 5.8 compatible. No provider setup, key rewriting, identity/confidence policy, filtering, eligibility, checkout changes or writes. Do not author or edit tests.\",\n  \"allowed_paths\": [\n    \"taggable-server/app/Services/RecognitionPurchaseEvidence.php\"\n  ],\n  \"baseline\": \"/Users/kamenkamenov/memory-knowledge/Tasks/taggable-cross-location-discount-atoms-20260911/selfie-purchase-lookup/baseline\",\n  \"files\": [\n    {\n      \"path\": \"probe.py\",\n      \"sha256\": \"bc43ff6657f033e71bd10cd8f032616cffd108965c0a5229a55fc8eb2f572e0f\"\n    },\n    {\n      \"path\": \"taggable-server/app/Helpers/AmazonFaceRecognitionService.php\",\n      \"sha256\": \"f2613f456ddc506941305c16aa3655dfe4fcee5268cbbf2a03dc24311dcd2825\"\n    },\n    {\n      \"path\": \"taggable-server/app/Order.php\",\n      \"sha256\": \"1a585e7399c5f54b2ad0c2a2d0f2354f132d071954d55187e0a82c8d89fc8e4a\"\n    },\n    {\n      \"path\": \"taggable-server/app/Payments.php\",\n      \"sha256\": \"33aeeaaa0b062315d2e45acce700b6ac7572f1e2ccf53521412dac60dd17b868\"\n    },\n    {\n      \"path\": \"taggable-server/app/Services/MatchedSearchOrders.php\",\n      \"sha256\": \"f5d79ed9825202d8010a28df6c20a5084bfda2f42f15f352d9b9b1f005122817\"\n    },\n    {\n      \"path\": \"taggable-server/app/Services/RecognitionPurchaseEvidence.php\",\n      \"sha256\": \"e4b90d24ef569612d0198ea6f75f9d289932be821fd952684cdffc8b961c5575\"\n    },\n    {\n      \"path\": \"taggable-server/app/Services/RecordedPaymentEvidence.php\",\n      \"sha256\": \"ee496abb2a5d70cec820194dfef86a2665ca7c1edc24ffd39a2fad10c1bdb006\"\n    },\n    {\n      \"path\": \"taggable-server/app/Services/SearchPaymentEvidence.php\",\n      \"sha256\": \"ea8f7cb94e5f5a3e6214a4a113836cc8a65d79254db975f18c0ec3aa66e353b0\"\n    },\n    {\n      \"path\": \"taggable-server/app/Services/SearchRecognitionRegistration.php\",\n      \"sha256\": \"7cd9e7c00ee72e920c058aef71dc00f326be9adc8a5e6e72e5631af294c83be5\"\n    },\n    {\n      \"path\": \"taggable-server/app/UserSelfieHistory.php\",\n      \"sha256\": \"71349c5a6b52e02108f6ab105b84917ccc388e2acc57005b591fce019f7b922b\"\n    },\n    {\n      \"path\": \"test.php\",\n      \"sha256\": \"549a469bc599efd0ced1536b9d0b3e7cac6c2c4fa7f8f2314ecff45fa8a9ef89\"\n    }\n  ],\n  \"source_units\": [\n    {\n      \"path\": \"taggable-server/app/Services/MatchedSearchOrders.php\",\n      \"text\": \"<?php\\n\\nnamespace App\\\\Services;\\n\\nuse App\\\\Order;\\nuse App\\\\UserSelfieHistory;\\nuse InvalidArgumentException;\\n\\nclass MatchedSearchOrders\\n{\\n    /**\\n     * Resolve an internal search-history ID to all explicitly linked orders.\\n     * The caller must establish the ID's provenance; this does not verify a\\n     * person, a recognition score, payment, or discount eligibility.\\n     *\\n     * @param int|string $historyId\\n     * @return \\\\Illuminate\\\\Database\\\\Eloquent\\\\Collection\\n     */\\n    public static function forHistoryId($historyId)\\n    {\\n        if ((!is_int($historyId) && !is_string($historyId)) ||\\n            filter_var($historyId, FILTER_VALIDATE_INT, ['options' => ['min_range' => 1]]) === false) {\\n            throw new InvalidArgumentException('A positive search-history ID is required.');\\n        }\\n\\n        $history = UserSelfieHistory::query()->findOrFail($historyId);\\n\\n        return Order::query()\\n            ->where('selfie_search_id', $history->getKey())\\n            ->orderBy('order_id')\\n            ->get();\\n    }\\n}\\n\"\n    },\n    {\n      \"path\": \"taggable-server/app/Services/RecognitionPurchaseEvidence.php\",\n      \"text\": \"<?php\\n\\nnamespace App\\\\Services;\\n\\nuse InvalidArgumentException;\\n\\nclass RecognitionPurchaseEvidence\\n{\\n    /**\\n     * Preserve every returned match alongside its complete reference evidence.\\n     * A successful empty list is distinct from provider failure sentinels.\\n     * This does not decide whether a match establishes identity or eligibility.\\n     */\\n    public static function forMatches($collectionId, $matches)\\n    {\\n        if ($collectionId !== SearchRecognitionRegistration::COLLECTION_ID || !is_array($matches)) {\\n            throw new InvalidArgumentException('The search collection and a successful match list are required.');\\n        }\\n\\n        $results = [];\\n        $index = 0;\\n        foreach ($matches as $key => $match) {\\n            if ($key !== $index || !is_array($match) || !array_key_exists('externalImageId', $match)) {\\n                throw new InvalidArgumentException('Each match must be an ordered list entry containing externalImageId.');\\n            }\\n            $results[] = [\\n                'match' => $match,\\n                'reference_evidence' => static::forReference($collectionId, $match['externalImageId']),\\n            ];\\n            $index++;\\n        }\\n\\n        return $results;\\n    }\\n\\n    /**\\n     * Resolve one reference in the caller's search collection context.\\n     * This does not authenticate the reference or establish a person match,\\n     * confidence, location eligibility, or entitlement to a discount.\\n     */\\n    public static function forReference($collectionId, $externalImageId)\\n    {\\n        $prefix = SearchRecognitionRegistration::EXTERNAL_ID_PREFIX;\\n        if ($collectionId !== SearchRecognitionRegistration::COLLECTION_ID ||\\n            !is_string($externalImageId) ||\\n            !preg_match('/\\\\\\\\A' . preg_quote($prefix, '/') . '([1-9][0-9]*)\\\\\\\\z/', $externalImageId, $matches)) {\\n            throw new InvalidArgumentException('A canonical search recognition reference is required.');\\n        }\\n\\n        $historyId = filter_var($matches[1], FILTER_VALIDATE_INT, ['options' => ['min_range' => 1]]);\\n        if ($historyId === false) {\\n            throw new InvalidArgumentException('The search recognition ID is outside the supported integer range.');\\n        }\\n\\n        return [\\n            'collection_id' => $collectionId,\\n            'external_image_id' => $externalImageId,\\n            'purchase_evidence' => SearchPaymentEvidence::forHistoryId($historyId),\\n        ];\\n    }\\n}\\n\"\n    },\n    {\n      \"path\": \"taggable-server/app/Services/RecordedPaymentEvidence.php\",\n      \"text\": \"<?php\\n\\nnamespace App\\\\Services;\\n\\nuse App\\\\Payments;\\nuse InvalidArgumentException;\\n\\nclass RecordedPaymentEvidence\\n{\\n    /**\\n     * Inspect application records, not gateway settlement or discount eligibility.\\n     * The caller must establish the order's search/person/location provenance.\\n     */\\n    public static function forOrderId($orderId)\\n    {\\n        if ((!is_int($orderId) && !is_string($orderId)) ||\\n            filter_var($orderId, FILTER_VALIDATE_INT, ['options' => ['min_range' => 1]]) === false) {\\n            throw new InvalidArgumentException('A positive order ID is required.');\\n        }\\n\\n        $payments = Payments::query()\\n            ->leftJoin('status', 'payment.status_id', '=', 'status.status_id')\\n            ->where('payment.order_id', $orderId)\\n            ->orderBy('payment.payment_id')\\n            ->get([\\n                'payment.payment_id', 'payment.amount', 'payment.deleted',\\n                'payment.transaction_id', 'payment.square_transaction_id',\\n                'payment.transaction_response_code', 'status.name as recorded_status',\\n            ]);\\n\\n        $classification = 'not-established';\\n        $records = [];\\n        foreach ($payments as $payment) {\\n            list($decision, $reason) = self::classifyRecord($payment);\\n            $records[] = [\\n                'payment_id' => $payment->payment_id,\\n                'classification' => $decision,\\n                'reason' => $reason,\\n            ];\\n            if ($decision === 'recorded-success' ||\\n                ($decision === 'unresolved' && $classification === 'not-established')) {\\n                $classification = $decision;\\n            }\\n        }\\n\\n        return ['order_id' => (int) $orderId, 'classification' => $classification, 'records' => $records];\\n    }\\n\\n    private static function classifyRecord(Payments $payment)\\n    {\\n        if ($payment->deleted !== null) {\\n            return ['not-established', 'deleted-record'];\\n        }\\n        if (in_array($payment->recorded_status, ['failed', 'active', 'payment canceled'], true)) {\\n            return ['not-established', 'non-success-status'];\\n        }\\n\\n        // Only the sign matters. Avoid rounding decimal payment amounts through floats.\\n        $amount = (string) $payment->amount;\\n        if (!preg_match('/^-?\\\\d+(?:\\\\.\\\\d+)?$/D', $amount)) {\\n            return ['unresolved', 'invalid-amount'];\\n        }\\n        if ($amount[0] === '-' || !preg_match('/[1-9]/', $amount)) {\\n            return ['not-established', 'nonpositive-amount'];\\n        }\\n        if ($payment->recorded_status !== 'approved') {\\n            return ['unresolved', 'unknown-status'];\\n        }\\n\\n        $square = trim((string) $payment->square_transaction_id) !== '';\\n        $transaction = trim((string) $payment->transaction_id) !== '';\\n        $response = (string) $payment->transaction_response_code;\\n        if ($square && !$transaction && $response === '') {\\n            return ['recorded-success', 'square-recorded-success'];\\n        }\\n        if ($transaction && !$square && $response === '1') {\\n            return ['recorded-success', 'authorize-recorded-success'];\\n        }\\n        if ($transaction && !$square && $response === 'succeeded') {\\n            return ['recorded-success', 'stripe-recorded-success'];\\n        }\\n\\n        return ['unresolved', 'unrecognized-success-format'];\\n    }\\n}\\n\"\n    },\n    {\n      \"path\": \"taggable-server/app/Services/SearchPaymentEvidence.php\",\n      \"text\": \"<?php\\n\\nnamespace App\\\\Services;\\n\\nclass SearchPaymentEvidence\\n{\\n    /**\\n     * Connect a supplied search to its recorded payment evidence.\\n     * This does not establish person identity, location eligibility or settlement.\\n     * Unknown and malformed history IDs retain the lookup service's exceptions.\\n     */\\n    public static function forHistoryId($historyId)\\n    {\\n        $linkedOrders = MatchedSearchOrders::forHistoryId($historyId);\\n        $orders = [];\\n        $classification = 'not-established';\\n\\n        foreach ($linkedOrders as $order) {\\n            $evidence = RecordedPaymentEvidence::forOrderId($order->order_id);\\n            $orders[] = $evidence;\\n\\n            if ($evidence['classification'] === 'recorded-success' ||\\n                ($evidence['classification'] === 'unresolved' && $classification === 'not-established')) {\\n                $classification = $evidence['classification'];\\n            }\\n        }\\n\\n        return [\\n            'search_history_id' => (int) $historyId,\\n            'classification' => $classification,\\n            'orders' => $orders,\\n        ];\\n    }\\n}\\n\"\n    },\n    {\n      \"path\": \"taggable-server/app/Services/SearchRecognitionRegistration.php\",\n      \"text\": \"<?php\\n\\nnamespace App\\\\Services;\\n\\nuse App\\\\Helpers\\\\AmazonFaceRecognitionService;\\nuse App\\\\UserSelfieHistory;\\nuse InvalidArgumentException;\\n\\nclass SearchRecognitionRegistration\\n{\\n    const COLLECTION_ID = 'purchase-search-history';\\n    const EXTERNAL_ID_PREFIX = 'search-history-';\\n\\n    /**\\n     * Register an explicitly supplied search using its own recognition reference.\\n     * The caller configures the helper. This does not establish a person match,\\n     * payment, location eligibility, or a durable local indexed flag.\\n     */\\n    public static function registerForHistoryId($historyId, AmazonFaceRecognitionService $amazon)\\n    {\\n        if ((!is_int($historyId) && !is_string($historyId)) ||\\n            filter_var($historyId, FILTER_VALIDATE_INT, ['options' => ['min_range' => 1]]) === false) {\\n            throw new InvalidArgumentException('A positive search-history ID is required.');\\n        }\\n\\n        $history = UserSelfieHistory::query()->findOrFail($historyId);\\n        // Only recorded presence matters here; no timestamp conversion is needed.\\n        $recorded = $history->getAttributes();\\n        if (empty($recorded['consent_given_at']) || empty($recorded['search_completed_at']) ||\\n            !is_array($history->matched_image_ids) || !$history->matched_image_ids) {\\n            throw new InvalidArgumentException('The search requires recorded consent and completed photo results.');\\n        }\\n\\n        $bucket = AmazonFaceRecognitionService::$AmazonFaceRecognitionBucketName;\\n        $region = AmazonFaceRecognitionService::$AmazonFaceRecognitionRegion;\\n        if ($history->storage_provider !== 'amazon' ||\\n            !is_string($history->s3_key) || trim($history->s3_key) === '' ||\\n            !is_string($bucket) || $bucket === '' || !is_string($region) || $region === '' ||\\n            $history->s3_bucket !== $bucket || $history->s3_region !== $region) {\\n            throw new InvalidArgumentException('The search image must belong to the configured Amazon bucket and region.');\\n        }\\n\\n        $result = [\\n            'search_history_id' => (int) $history->getKey(),\\n            'collection_id' => self::COLLECTION_ID,\\n            'external_image_id' => self::EXTERNAL_ID_PREFIX . $history->getKey(),\\n            'status' => 'not-registered',\\n            'face_ids' => [],\\n        ];\\n\\n        if ($amazon->createCollection(self::COLLECTION_ID) !== true) {\\n            return $result;\\n        }\\n\\n        $faceIds = $amazon->indexFaceInCollection(\\n            $history->s3_key,\\n            self::COLLECTION_ID,\\n            $result['external_image_id']\\n        );\\n        if (!is_array($faceIds) || count($faceIds) !== 1 ||\\n            !isset($faceIds[0]) || !is_string($faceIds[0]) || trim($faceIds[0]) === '') {\\n            return $result;\\n        }\\n\\n        $result['status'] = 'registered';\\n        $result['face_ids'] = $faceIds;\\n\\n        return $result;\\n    }\\n}\\n\"\n    },\n    {\n      \"path\": \"taggable-server/app/Helpers/AmazonFaceRecognitionService.php\",\n      \"text\": \"    public function searchFacesByImage($s3Key, $collectionId, $maxFaces = 100, $threshold = 80.0) {\\n        try {\\n            $client = new \\\\GuzzleHttp\\\\Client(['base_uri' => self::$AmazonFaceRecognitionURL]);\\n            $raw_body = [\\n                \\\"CollectionId\\\" => $collectionId,\\n                \\\"Image\\\" => [\\n                    \\\"S3Object\\\" => [\\n                        \\\"Bucket\\\" => self::$AmazonFaceRecognitionBucketName,\\n                        \\\"Name\\\" => $s3Key\\n                    ]\\n                ],\\n                \\\"MaxFaces\\\" => (int)$maxFaces,\\n                \\\"FaceMatchThreshold\\\" => (float)$threshold,\\n            ];\\n\\n            $json_body = json_encode($raw_body);\\n            $headers = self::getHeaders('POST', 'RekognitionService.SearchFacesByImage', $json_body);\\n            $data = [\\n                'headers' => $headers,\\n                'body' => $json_body\\n            ];\\n\\n            Log::debug(\\\"AMAZON DATA searchFacesByImage: \\\".json_encode($data));\\n            $result = $client->request('POST', '', $data);\\n\\n            if ($result->getStatusCode() == 200) {\\n                $matches = [];\\n                $response = json_decode($result->getBody()->getContents());\\n                foreach ($response->FaceMatches as $faceMatch) {\\n                    $matches[] = [\\n                        'faceId' => $faceMatch->Face->FaceId,\\n                        'externalImageId' => $faceMatch->Face->ExternalImageId,\\n                        'similarity' => (float)$faceMatch->Similarity,\\n                    ];\\n                }\\n                Log::debug(\\\"AMAZON searchFacesByImage matches: \\\".json_encode($matches));\\n                return $matches;\\n            } else {\\n                Log::debug('AMAZON searchFacesByImage: unexpected status code: '.$result->getStatusCode());\\n                return false;\\n            }\\n        } catch (\\\\GuzzleHttp\\\\Exception\\\\RequestException $ex) {\\n            $message = $ex->getMessage();\\n            $responseBody = '';\\n            if ($ex->hasResponse()) {\\n                $responseBody = (string) $ex->getResponse()->getBody();\\n            }\\n            if (strpos($message, 'InvalidParameterException') !== false\\n                || strpos($responseBody, 'InvalidParameterException') !== false) {\\n                Log::debug('AMAZON searchFacesByImage: no face detected in image');\\n                return 'no_face';\\n            }\\n            if (strpos($message, 'ResourceNotFoundException') !== false\\n                || strpos($responseBody, 'ResourceNotFoundException') !== false) {\\n                Log::error('AMAZON searchFacesByImage: collection not found: '.$collectionId);\\n                return 'no_collection';\\n            }\\n            Log::error('AMAZON searchFacesByImage: exception: '.$message);\\n            return false;\\n        }\\n    }\\n\"\n    }\n  ],\n  \"context\": \"{\\\"case_contract\\\": {\\\"contract\\\": \\\"Query the fixed registered-search collection using the exact caller-supplied selfie key and configured existing helper, then return complete existing forMatches evidence. Preserve helper default maxFaces and threshold. Failure sentinels must remain invalid-match-list refusals, missing history must propagate, no partial success or writes. This reports candidate matches and payments, not identity, prior-location qualification or discount entitlement.\\\", \\\"source\\\": {\\\"path\\\": \\\"/Users/kamenkamenov/memory-knowledge/Tasks/taggable-cross-location-discount-atoms-20260911/admitted-atom-execution/transport-driver-inputs/cases.json\\\", \\\"sha256\\\": \\\"a3d0aa916a8f3fc7311ea1056729e1b49d3c3d8e7045b786db3291c07de27204\\\"}, \\\"cases\\\": [{\\\"id\\\": \\\"empty-matches\\\", \\\"kind\\\": \\\"success\\\", \\\"histories\\\": [11, 22], \\\"orders\\\": [{\\\"order_id\\\": 101, \\\"selfie_search_id\\\": 11, \\\"status_id\\\": 4}], \\\"payments\\\": [{\\\"payment_id\\\": 501, \\\"order_id\\\": 101, \\\"status\\\": \\\"approved\\\", \\\"amount\\\": \\\"10.00\\\", \\\"transaction_id\\\": null, \\\"square_transaction_id\\\": \\\"controlled-square\\\", \\\"transaction_response_code\\\": null, \\\"deleted\\\": null}], \\\"collection_id\\\": \\\"purchase-search-history\\\", \\\"matches\\\": [], \\\"expected\\\": []}, {\\\"id\\\": \\\"one-paid-match\\\", \\\"kind\\\": \\\"success\\\", \\\"histories\\\": [11, 22], \\\"orders\\\": [{\\\"order_id\\\": 101, \\\"selfie_search_id\\\": 11, \\\"status_id\\\": 4}], \\\"payments\\\": [{\\\"payment_id\\\": 501, \\\"order_id\\\": 101, \\\"status\\\": \\\"approved\\\", \\\"amount\\\"