public function searchFacesByImage($s3Key, $collectionId, $maxFaces = 100, $threshold = 80.0) {
    try {
        $client = new \GuzzleHttp\Client(['base_uri' => self::$AmazonFaceRecognitionURL]);
        $raw_body = [
            "CollectionId" => $collectionId,
            "Image" => [
                "S3Object" => [
                    "Bucket" => self::$AmazonFaceRecognitionBucketName,
                    "Name" => $s3Key
                ]
            ],
            "MaxFaces" => (int)$maxFaces,
            "FaceMatchThreshold" => (float)$threshold,
        ];

        $json_body = json_encode($raw_body);
        $headers = self::getHeaders('POST', 'RekognitionService.SearchFacesByImage', $json_body);
        $data = [
            'headers' => $headers,
            'body' => $json_body
        ];

        Log::debug("AMAZON DATA searchFacesByImage: ".json_encode($data));
        $result = $client->request('POST', '', $data);

        if ($result->getStatusCode() == 200) {
            $matches = [];
            $response = json_decode($result->getBody()->getContents());
            foreach ($response->FaceMatches as $faceMatch) {
                $matches[] = [
                    'faceId' => $faceMatch->Face->FaceId,
                    'externalImageId' => $faceMatch->Face->ExternalImageId,
                    'similarity' => (float)$faceMatch->Similarity,
                ];
            }
            Log::debug("AMAZON searchFacesByImage matches: ".json_encode($matches));
            return $matches;
        } else {
            Log::debug('AMAZON searchFacesByImage: unexpected status code: '.$result->getStatusCode());
            return false;
        }
    } catch (\GuzzleHttp\Exception\RequestException $ex) {
        $message = $ex->getMessage();
        $responseBody = '';
        if ($ex->hasResponse()) {
            $responseBody = (string) $ex->getResponse()->getBody();
        }
        if (strpos($message, 'InvalidParameterException') !== false
            || strpos($responseBody, 'InvalidParameterException') !== false) {
            Log::debug('AMAZON searchFacesByImage: no face detected in image');
            return 'no_face';
        }
        if (strpos($message, 'ResourceNotFoundException') !== false
            || strpos($responseBody, 'ResourceNotFoundException') !== false) {
            Log::error('AMAZON searchFacesByImage: collection not found: '.$collectionId);
            return 'no_collection';
        }
        Log::error('AMAZON searchFacesByImage: exception: '.$message);
        return false;
    }
}

